WITH recent_payments AS (SELECT * FROM payments WHERE method = 'promptpay' AND amount <= 510), status_group_summary AS (SELECT CASE WHEN status IN ('FAILED', 'REFUNDED') THEN 'priority' ELSE 'other' END AS status_group, COUNT(amount) AS amount_count, ROUND(AVG(amount), 2) AS avg_amount FROM recent_payments GROUP BY CASE WHEN status IN ('FAILED', 'REFUNDED') THEN 'priority' ELSE 'other' END) SELECT * FROM status_group_summary WHERE amount_count > 8 ORDER BY avg_amount DESC, status_group LIMIT 10;
